def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    cols=[c for c in range(1,w-1) if grid[0][c]!=0 and all(grid[r][c]==grid[0][c] for r in range(h))]
    rows=[r for r in range(1,h-1) if grid[r][0]!=0 and all(v==grid[r][0] for v in grid[r])]
    if cols:
        c=min(cols,key=lambda c:abs(2*c+1-w)); n=min(c,w-c-1)
        for r in range(h):
            for j in range(n):
                a,b=grid[r][j],grid[r][c+1+j]
                if a==0 or b==0: out[r][j],out[r][c+1+j]=b,a
    elif rows:
        r=min(rows,key=lambda r:abs(2*r+1-h)); n=min(r,h-r-1)
        for i in range(n):
            for c in range(w):
                a,b=grid[i][c],grid[r+1+i][c]
                if a==0 or b==0: out[i][c],out[r+1+i][c]=b,a
    return out

